&lt;td&gt;&lt;code&gt;hi&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;Devanagari&lt;/td&gt;
&lt;td&gt;
&lt;code&gt;one&lt;/code&gt; / &lt;code&gt;other&lt;/code&gt; (2)&lt;/td&gt;
&lt;td&gt;
&lt;code&gt;0/1 गोल&lt;/code&gt; / &lt;code&gt;2 गोल&lt;/code&gt;
&lt;/td&gt;
&lt;td&gt;
&lt;code&gt;0/1 गोल&lt;/code&gt; / &lt;code&gt;2 गोल&lt;/code&gt;
&lt;/td&gt;
&lt;td&gt;✅ Identical (&lt;code&gt;0-as-one&lt;/code&gt;)&lt;/td&gt;
